import{_ as t,o as s,c as a,ag as o}from"./chunks/framework.DoUXNnsN.js";const k=JSON.parse('{"title":"Docker镜像与容器","description":"","frontmatter":{"title":"Docker镜像与容器","aliases":["Docker image","Docker container","docker run","数据卷","端口映射","Docker Hub"],"tags":["工具与工程","Docker"],"status":"ai-draft","sources":["https://docs.docker.com/get-started/docker-overview/","https://docs.docker.com/reference/cli/docker/container/run/","https://learn.microsoft.com/en-us/dotnet/core/docker/build-container","https://learn.microsoft.com/en-us/sql/linux/sql-server-linux-docker-container-deployment","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":2},"headers":[],"relativePath":"50-工具与工程/Docker/Docker镜像与容器.md","filePath":"50-工具与工程/Docker/Docker镜像与容器.md"}'),d={name:"50-工具与工程/Docker/Docker镜像与容器.md"};function i(r,e,c,l,n,h){return s(),a("div",null,[...e[0]||(e[0]=[o(`<blockquote class="callout-warn"><p>⚠ 未在本机运行验证：本机没有安装 Docker，本篇所有 <code>docker</code> 命令和输出均来自官方文档与模型知识，未亲手运行；已登记到待核对清单。MCR 上 <code>mcr.microsoft.com/mssql/server:2022-latest</code> 等标签已通过查询其标签列表确认存在。</p></blockquote><blockquote><p>本篇是 <a href="/Encyclopedia/50-工具与工程/Docker/Docker">Docker</a> 入门路径的第 2 篇（共 4 篇）。读完你应该能：用 <code>docker run</code> 启动、停止、删除容器；解释端口映射 <code>-p</code> 和数据卷 <code>-v</code> 各自解决什么问题；起一个 SQL Server 容器并保证数据不丢。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p><strong>镜像</strong>是只读的、分层的程序包；<strong>容器</strong>是用镜像启动出来的、带有一层可写空间的运行实例。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/50-工具与工程/Docker/Docker">Docker</a>：知道镜像、容器、仓库是什么。</li><li><a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a>：会在终端里敲命令。</li><li><a href="/Encyclopedia/10-计算机基础/计算机网络/TCP-IP">TCP-IP</a>：知道端口是什么。</li><li><a href="/Encyclopedia/10-计算机基础/操作系统/文件系统">文件系统</a>：知道&quot;目录&quot;&quot;挂载&quot;的大致含义。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>只知道&quot;镜像是模板、容器是实例&quot;还不够，真正用起来会立刻遇到三个问题：</p><ol><li><strong>容器里的服务，我从外面怎么访问？</strong> 容器有自己的网络，默认外部连不进去 → <strong>端口映射</strong>。</li><li><strong>容器删了，里面的数据（比如数据库）也没了怎么办？</strong> → <strong>数据卷</strong>。</li><li><strong>同一个镜像，怎么在不同场合配不同的设置（密码、模式）？</strong> → <strong>环境变量</strong>。</li></ol><p>本篇围绕这三件事展开。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="镜像-分层、有名字、有标签" tabindex="-1">镜像：分层、有名字、有标签 <a class="header-anchor" href="#镜像-分层、有名字、有标签" aria-label="Permalink to &quot;镜像：分层、有名字、有标签&quot;">​</a></h3><p>镜像的完整名字长这样：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcr.microsoft.com/mssql/server:2022-latest</span></span>
<span class="line"><span>└──────┬───────┘ └────┬─────┘ └────┬────┘</span></span>
<span class="line"><span>   仓库地址        仓库内的名字     标签（版本）</span></span></code></pre></div><ul><li>省略仓库地址时默认是 Docker Hub，例如 <code>redis:alpine</code>、<code>python:3.12-slim</code>。</li><li>**标签（tag）**通常表示版本。不写标签等于 <code>latest</code>，但 <code>latest</code> 会随时间变化，<strong>正式场合应写明确的版本</strong>。</li><li>微软的镜像放在自家的 MCR（Microsoft Container Registry，<code>mcr.microsoft.com</code>）。</li></ul><p><strong>分层</strong>：镜像由多个只读层叠成。官方文档说，Dockerfile 里每条指令会增加一层，重新构建时只重建变化的层，所以又快又省空间。不同镜像如果用了相同的底层（比如都基于同一个 Linux 基础镜像），这些层在磁盘上只存一份。</p><h3 id="容器-镜像-一层可写层" tabindex="-1">容器：镜像 + 一层可写层 <a class="header-anchor" href="#容器-镜像-一层可写层" aria-label="Permalink to &quot;容器：镜像 + 一层可写层&quot;">​</a></h3><p>启动容器时，Docker 在镜像的只读层之上加一层<strong>可写层</strong>。你在容器里创建、修改的文件都写在这一层。官方文档的说法是：没有保存在持久存储里的状态，会在容器被删除时丢失。所以：</p><ul><li>容器是<strong>一次性</strong>的、可随时删掉重建的；</li><li>要保留的数据必须放在<strong>数据卷</strong>里。</li></ul><p>容器有几种状态：</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>进入方式</th></tr></thead><tbody><tr><td>Created</td><td>创建了但没启动</td><td><code>docker create</code></td></tr><tr><td>Up（running）</td><td>正在运行</td><td><code>docker start</code> / <code>docker run</code></td></tr><tr><td>Exited</td><td>里面的主进程结束了</td><td>程序自己退出，或 <code>docker stop</code></td></tr></tbody></table><p><strong>关键理解</strong>：容器的生命周期 = 它里面<strong>主进程</strong>的生命周期。官方教程里 <code>ENTRYPOINT</code> 指定的命令一结束，容器就自动停止。因此&quot;容器启动后立刻退出&quot;多半是因为主进程跑完了或崩溃了，不是 Docker 坏了。</p><h3 id="常用命令速查" tabindex="-1">常用命令速查 <a class="header-anchor" href="#常用命令速查" aria-label="Permalink to &quot;常用命令速查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>docker pull 镜像</code></td><td>从仓库下载镜像</td></tr><tr><td><code>docker images</code></td><td>列出本地镜像</td></tr><tr><td><code>docker run 镜像</code></td><td>创建并启动容器（= create + start）</td></tr><tr><td><code>docker ps</code></td><td>列出<strong>正在运行</strong>的容器；加 <code>-a</code> 列出所有</td></tr><tr><td><code>docker stop 名字</code></td><td>停止容器</td></tr><tr><td><code>docker start 名字</code></td><td>重新启动已停止的容器</td></tr><tr><td><code>docker rm 名字</code></td><td>删除容器（须先停止，或加 <code>-f</code>）</td></tr><tr><td><code>docker rmi 镜像</code></td><td>删除镜像</td></tr><tr><td><code>docker logs 名字</code></td><td>查看容器输出的日志，<code>-f</code> 持续跟随</td></tr><tr><td><code>docker exec -it 名字 bash</code></td><td>进入运行中的容器开一个终端</td></tr></tbody></table><h3 id="docker-run-的常用开关" tabindex="-1">docker run 的常用开关 <a class="header-anchor" href="#docker-run-的常用开关" aria-label="Permalink to &quot;docker run 的常用开关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>开关</th><th>含义</th></tr></thead><tbody><tr><td><code>--name x</code></td><td>给容器起名字，不起则随机生成</td></tr><tr><td><code>-d</code></td><td>后台运行（detached）</td></tr><tr><td><code>-it</code></td><td>交互式终端（<code>-i</code> 保持输入，<code>-t</code> 分配终端）</td></tr><tr><td><code>--rm</code></td><td>容器停止后自动删除，适合一次性任务</td></tr><tr><td><code>-e 变量=值</code></td><td>设置环境变量</td></tr><tr><td><code>-p 主机端口:容器端口</code></td><td>端口映射</td></tr><tr><td><code>-v 卷名或路径:容器路径</code></td><td>挂载数据卷或目录</td></tr><tr><td><code>--entrypoint</code></td><td>临时替换镜像里的入口命令</td></tr></tbody></table><h3 id="端口映射-p" tabindex="-1">端口映射 <code>-p</code> <a class="header-anchor" href="#端口映射-p" aria-label="Permalink to &quot;端口映射 \`-p\`&quot;">​</a></h3><p>容器有独立的网络空间。SQL Server 在容器里监听 1433，但这是<strong>容器内部</strong>的 1433。要让你电脑上的程序连上，要加 <code>-p 11433:1433</code>，意思是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的电脑:11433  ──转发──►  容器:1433</span></span></code></pre></div><p>左边是主机端口，右边是容器端口，<strong>左主右容</strong>。主机端口不能和别的程序冲突——比如你本机已经装了 SQL Server（占着 1433），再起容器写 <code>-p 1433:1433</code> 就会失败或冲突，改成 <code>-p 11433:1433</code> 即可。官方文档的多容器示例也是靠映射到 <code>1401</code>、<code>1402</code> 来在同一台机器上跑两个 SQL Server。</p><p>连接时用 <code>localhost,11433</code>（SQL Server 的写法是逗号分隔端口）。</p><h3 id="数据卷-v" tabindex="-1">数据卷 <code>-v</code> <a class="header-anchor" href="#数据卷-v" aria-label="Permalink to &quot;数据卷 \`-v\`&quot;">​</a></h3><p>数据卷（volume）是 Docker 管理的、<strong>独立于容器生命周期</strong>的存储。两种常见写法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-v sqldata:/var/opt/mssql        # 具名卷：Docker 管理位置，推荐用于数据库</span></span>
<span class="line"><span>-v D:\\data\\sql:/var/opt/mssql    # 绑定挂载：直接把主机上的目录挂进去</span></span></code></pre></div><p><code>/var/opt/mssql</code> 是官方 SQL Server 镜像存放数据文件的位置（官方文档在&quot;数据持久化&quot;章节说明）。删除容器后，具名卷还在；用同样的 <code>-v</code> 再起一个新容器，数据就回来了。</p><h2 id="逐步例子" tabindex="-1">逐步例子 <a class="header-anchor" href="#逐步例子" aria-label="Permalink to &quot;逐步例子&quot;">​</a></h2><h3 id="例-1-官方-net-计数器-输出引自官方文档-⚠-未在本机验证" tabindex="-1">例 1：官方 .NET 计数器（输出引自官方文档，⚠ 未在本机验证） <a class="header-anchor" href="#例-1-官方-net-计数器-输出引自官方文档-⚠-未在本机验证" aria-label="Permalink to &quot;例 1：官方 .NET 计数器（输出引自官方文档，⚠ 未在本机验证）&quot;">​</a></h3><p>官方教程里有一个每秒数一个数的程序，镜像名 <code>counter-image</code>（下一篇 <a href="/Encyclopedia/50-工具与工程/Docker/Dockerfile">Dockerfile</a> 教你怎么构建）：</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">docker run -it --rm counter-image 3</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Counter: 1</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Counter: 2</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Counter: 3</span></span></code></pre></div><p>拆解：</p><ol><li><code>-it</code>：接上你的终端，才能看到输出、按 Ctrl+C。</li><li><code>--rm</code>：程序数到 3 退出，容器随即自动删除。</li><li>末尾的 <code>3</code>：<strong>跟在镜像名后面的内容会作为参数传给容器的入口程序</strong>（官方文档：<code>docker run</code> 的参数会追加到 exec 形式的 ENTRYPOINT 后面）。</li></ol><p>然后用 <code>docker ps -a</code> 验证：因为有 <code>--rm</code>，列表里应该没有这个容器。</p><h3 id="例-2-运行-sql-server-并保住数据-⚠-未在本机验证" tabindex="-1">例 2：运行 SQL Server 并保住数据（⚠ 未在本机验证） <a class="header-anchor" href="#例-2-运行-sql-server-并保住数据-⚠-未在本机验证" aria-label="Permalink to &quot;例 2：运行 SQL Server 并保住数据（⚠ 未在本机验证）&quot;">​</a></h3><p>命令基于微软官方文档，加了 <code>--name</code>、具名卷和非默认端口。PowerShell 写法：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name mssql</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lab </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ACCEPT_EULA=Y&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MSSQL_SA_PASSWORD=Lab_Passw0rd!2026&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> \`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11433</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1433</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> \`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v sqldata:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/var/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">opt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mssql </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">mcr.microsoft.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mssql</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2022</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">latest</span></span></code></pre></div><p>逐项解释：</p><table tabindex="0"><thead><tr><th>部分</th><th>含义</th></tr></thead><tbody><tr><td><code>ACCEPT_EULA=Y</code></td><td>接受微软的许可协议（官方镜像要求，不设则容器不会启动）</td></tr><tr><td><code>MSSQL_SA_PASSWORD</code></td><td><code>sa</code> 账户的密码。官方：<code>SA_PASSWORD</code> 已弃用，应使用 <code>MSSQL_SA_PASSWORD</code></td></tr><tr><td>密码规则</td><td>至少 8 位，且包含大写、小写、数字、符号四类中的三类（官方文档，可达 128 位）</td></tr><tr><td><code>-p 11433:1433</code></td><td>主机 11433 → 容器 1433</td></tr><tr><td><code>-v sqldata:/var/opt/mssql</code></td><td>数据放进具名卷 <code>sqldata</code></td></tr><tr><td><code>-d</code></td><td>后台运行</td></tr></tbody></table><blockquote><p>注意：Bash 里密码带 <code>!</code> 时，要用<strong>单引号</strong>包起来（<code>-e &#39;MSSQL_SA_PASSWORD=...&#39;</code>），否则 <code>!</code> 会触发历史展开。PowerShell 里用双引号即可。</p></blockquote><p>SQL Server 启动需要十几秒。用 <code>docker logs mssql-lab</code> 能看到启动日志，看到类似&quot;可以接受连接&quot;的提示后，用容器里自带的 sqlcmd 检查（路径来自官方文档）：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker exec </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">it mssql</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lab </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">opt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mssql</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tools18</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sqlcmd </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">S localhost </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">U sa </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">P </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Lab_Passw0rd!2026&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">No </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Q </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SELECT @@VERSION&quot;</span></span></code></pre></div><p>官方说明：新版 sqlcmd（mssql-tools18）默认强制加密，连不上时加 <code>-No</code> 表示加密为可选。</p><p>从主机连接：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sqlcmd -S localhost,11433 -U sa -P &quot;Lab_Passw0rd!2026&quot; -No</span></span></code></pre></div><h3 id="例-3-验证数据真的保住了" tabindex="-1">例 3：验证数据真的保住了 <a class="header-anchor" href="#例-3-验证数据真的保住了" aria-label="Permalink to &quot;例 3：验证数据真的保住了&quot;">​</a></h3><ol><li>连上去建库：<code>CREATE DATABASE DockerLab;</code></li><li><code>docker stop mssql-lab</code>，然后 <code>docker rm mssql-lab</code>：容器没了。</li><li>用<strong>完全相同</strong>的 <code>docker run</code> 命令再起一个（同样的 <code>-v sqldata:...</code>）。</li><li>再查 <code>SELECT name FROM sys.databases</code>：<code>DockerLab</code> 还在。</li></ol><p>如果第 3 步没写 <code>-v</code>，<code>DockerLab</code> 就消失了——这就是数据卷的作用。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p>按顺序做，每步后用 <code>docker ps -a</code> 观察状态变化（<strong>⚠ 未在本机运行验证</strong>）：</p><ol><li><code>docker run --name t1 --rm alpine echo hello</code>：<code>alpine</code> 是只有几 MB 的小 Linux。应打印 <code>hello</code> 并立刻退出，容器自动删除。</li><li><code>docker run -d --name t2 alpine sleep 300</code>：后台跑一个睡 300 秒的容器，<code>docker ps</code> 能看到它在 Up 状态。</li><li><code>docker exec -it t2 sh</code>：进入容器；在里面 <code>ls /</code>、<code>hostname</code> 看看；<code>exit</code> 退出，容器仍在运行。</li><li><code>docker stop t2</code> 后再 <code>docker ps -a</code>：状态变为 Exited。<code>docker rm t2</code> 清理。</li><li>把上面&quot;例 2&quot;的 SQL Server 容器按&quot;例 3&quot;的步骤做一遍，亲眼确认数据卷保住了数据。</li><li>完成后清理：<code>docker rm -f mssql-lab</code>，<code>docker volume rm sqldata</code>。</li></ol><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因与办法</th></tr></thead><tbody><tr><td>SQL Server 容器启动后马上退出</td><td>先 <code>docker logs 名字</code>。最常见：没设 <code>ACCEPT_EULA=Y</code>，或密码不满足复杂度要求</td></tr><tr><td>主机连不上 <code>localhost,11433</code></td><td>容器刚启动，SQL Server 还没就绪（等十几秒）；或端口映射写反了；或主机端口被占用</td></tr><tr><td>端口已被占用报错</td><td>换一个主机端口，如把 <code>-p 1433:1433</code> 改成 <code>-p 11433:1433</code></td></tr><tr><td>删容器后数据没了</td><td>忘了 <code>-v</code>。数据卷要在<strong>首次 <code>docker run</code></strong> 就挂上</td></tr><tr><td>Windows 本机 <code>curl localhost:端口</code> 返回 503</td><td>不是容器的问题：本机设了 <code>HTTP_PROXY</code> 环境变量，curl 把对本地地址的请求也交给了代理，代理返回 503。加 <code>--noproxy &#39;*&#39;</code> 或设置 <code>NO_PROXY</code>，详见 <a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a></td></tr><tr><td>官方 SQL Server 镜像在 ARM 电脑（如苹果芯片）上跑不起来</td><td>官方文档称容器镜像仅支持 x86-64 的 Intel/AMD CPU，模拟环境不受支持</td></tr><tr><td><code>docker rm</code> 提示容器还在运行</td><td>先 <code>docker stop</code>，或 <code>docker rm -f</code></td></tr></tbody></table><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><p><strong>1.</strong> <code>-p 8080:80</code> 里哪个是主机端口、哪个是容器端口？浏览器该访问哪个？</p><p>答：8080 是主机端口，80 是容器端口。浏览器访问 <code>http://localhost:8080</code>。</p><p><strong>2.</strong> 同一台机器要同时跑 SQL Server 2019 和 2022 两个容器，怎么避免冲突？</p><p>答：容器名不同，主机端口不同，如 <code>-p 1401:1433</code> 和 <code>-p 1402:1433</code>（官方文档的做法）；数据卷名也不同，避免两个版本共用同一份数据。</p><p><strong>3.</strong> 容器启动后秒退，第一步查什么？</p><p>答：<code>docker logs 容器名</code>，看主进程为什么退出。</p><p><strong>4.</strong> 为什么&quot;数据库放进容器&quot;一定要配数据卷？</p><p>答：容器可写层随容器删除而丢失；数据卷独立于容器，删容器后仍在，新容器挂上同一个卷就能继续用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>镜像 = 只读分层模板，用 <code>仓库/名字:标签</code> 定位；容器 = 镜像 + 可写层，是一次性的。</li><li>容器生命周期跟随主进程；排错先 <code>docker logs</code>。</li><li><code>-p 主机:容器</code> 解决访问，<code>-v</code> 解决数据持久，<code>-e</code> 解决配置。</li><li>SQL Server 容器：<code>ACCEPT_EULA=Y</code> + <code>MSSQL_SA_PASSWORD</code> + 复杂密码 + 数据卷 <code>/var/opt/mssql</code>。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/50-工具与工程/Docker/Docker">Docker</a>、<a href="/Encyclopedia/50-工具与工程/Docker/Dockerfile">Dockerfile</a>、<a href="/Encyclopedia/50-工具与工程/Docker/Docker-Compose">Docker-Compose</a>、<a href="/Encyclopedia/40-数据库/SQL-Server/SQL-Server">SQL-Server</a>、<a href="/Encyclopedia/10-计算机基础/计算机网络/TCP-IP">TCP-IP</a>、<a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a>、<a href="/Encyclopedia/10-计算机基础/操作系统/文件系统">文件系统</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><code>docker run</code> 参考：<a href="https://docs.docker.com/reference/cli/docker/container/run/" target="_blank" rel="noreferrer">https://docs.docker.com/reference/cli/docker/container/run/</a></li><li>微软：SQL Server 容器部署与连接：<a href="https://learn.microsoft.com/en-us/sql/linux/sql-server-linux-docker-container-deployment" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/sql/linux/sql-server-linux-docker-container-deployment</a></li><li>微软：用 Docker 容器化 .NET 应用：<a href="https://learn.microsoft.com/en-us/dotnet/core/docker/build-container" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/dotnet/core/docker/build-container</a></li></ul>`,76)])])}const g=t(d,[["render",i]]);export{k as __pageData,g as default};
